'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var exp = require( '@stdlib/math/base/special/exp' );
var pow = require( '@stdlib/math/base/special/pow' );
var erfc = require( '@stdlib/math/base/special/erfc' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );


// FUNCTIONS //

/**
* Evaluates the moment-generating function (MGF) for a degenerate distribution.
*
* @private
* @param {number} t - input value
* @returns {number} evaluated MGF
*/
function mgf0( t ) {
	return ( t === 0.0 ) ? 1.0 : NaN;
}


// MAIN //

/**
* Returns a function for evaluating the moment-generating function (MGF) for a half-normal distribution.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} function to evaluate the moment-generating function
*
* @example
* var mgf = factory( 2.0 );
* var y = mgf( 0.5 );
* // returns 2.7742859576700094
*
* y = mgf( 0.0 );
* // returns 1.0
*/
function factory( sigma ) {
	if (
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( sigma === 0.0 ) {
		return mgf0;
	}
	return mgf;

	/**
	* Evaluates the moment-generating function (MGF) for a half-normal distribution.
	*
	* @private
	* @param {number} t - input value
	* @returns {number} evaluated MGF
	*
	* @example
	* var y = mgf( 0.5 );
	* // returns <number>
	*/
	function mgf( t ) {
		var st;
		if ( isnan( t ) ) {
			return NaN;
		}
		st = sigma * t;
		return exp( pow( st, 2.0 ) / 2.0 ) * erfc( -st / SQRT2 );
	}
}


// EXPORTS //

module.exports = factory;
